echo json_encode(array('error' => 'Access denied. You do not have permission to access this resource.'));
exit;
?>
```

**Deny Access Function (Go)**
```go
package main

import (
    "net/http"
)

func denyAccess(w http.ResponseWriter, r *http.Request) {
    http.Error(w, "Access denied. You do not have permission to access this resource.", http.StatusForbidden)
}

func main() {
    http.HandleFunc("/", denyAccess)
    http.ListenAndServe(":8080", nil)
}
```

**Deny Access Function (Java)**
```java
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.ResponseStatus;

@RestController
public class DenyAccessController {
    @GetMapping("/")
    @ResponseStatus(HttpStatus.FORBIDDEN)
    public String denyAccess() {
        return "Access denied. You do not have permission to access this resource.";
    }
}
```

In each of these examples, the script returns a 403 Forbidden error message when the user attempts to access the website or service.
